/**
 * Candidate-isolated witness for the BS9-106～108 Chess Piece triggers.
 * Shadow Milk's real hand-discard decision is left open so the Browser lane
 * can select the physical Chess Piece card and let the shared command path
 * enqueue its passive effect.  The negative route changes only the source
 * name, proving that an unrelated effect cannot fire the trigger.
 */
function createBs9ChessPieceTriggerDemoState(cardNumber: string): GameState {
  const base = createBs9102ExtraDeckDemoState(true, 'BS9-102')
  const target = cardCheckOfficialCookie(cardNumber, `bs9-${cardNumber.toLowerCase()}-trigger-card`)
  const shadowMilk = cardCheckOfficialCookie('BS9-079', `bs9-${cardNumber.toLowerCase()}-shadow-milk`)
  const sourceEntry = cardCheckBattleEntry(
    shadowMilk,
    bs9PhysicalHpCards(shadowMilk.instanceId, shadowMilk.hp, shadowMilk.energyColor),
    9,
  )
  const player = base.players['player-one']
  return {
    ...base,
    activePlayerId: 'player-one',
    pendingOpponentHandDiscard: {
      playerId: 'player-one',
      count: 1,
      sourcePlayerId: 'player-one',
      sourceInstanceId: shadowMilk.instanceId,
      sourceCardName: shadowMilk.name,
      effectText: `Place ${target.name} from your hand into your trash by the effect of your [Shadow Milk Cookie].`,
      cookieOnly: true,
      destination: 'trash',
    },
    players: {
      ...base.players,
      'player-one': {
        ...player,
        hand: [target],
        battleArea: [sourceEntry, ...player.battleArea],
      },
    },
  }
}

/**
 * BS9-030 Shadow Milk Cookie 的 localhost-only EXTRA fixture。正向路徑使用
 * 四張真實黃色 FLIP Cookie 中支付三張登場代價，留下 1 張供攻擊後續使用；
 * 登場後可選擇休息區 LV.1 目標，再以三張黃色支援發動攻擊後的「棄置 FLIP
 * 並發動其效果」。負向路徑只保留兩張合格手牌，讓同一個 EXTRA 按鈕由規則層停用。
 */
function createBs9030ExtraDeckDemoState(
  conditionMet: boolean,
  variantCardNumber = 'BS9-030',
): GameState {
  const base = createBs8ExtraDeckDemoState(false)
  const source = (bs9CandidateDocument.cards as OfficialCardRecord[]).find(
    (record) => record.cardNumber === variantCardNumber,
  ) ?? (bs9CandidateDocument.cards as OfficialCardRecord[]).find(
    (record) => record.baseCardNumber === 'BS9-030',
  )
  if (!source) throw new Error('BS9-030 fixture requires the candidate EXTRA record')
  const conversion = convertOfficialCardToExtraDeckCard(source, 'bs9-030-demo')
  if (conversion.status !== 'converted') {
    throw new Error(`BS9-030 fixture cannot convert the candidate EXTRA card: ${conversion.reason}`)
  }
  const extraCard: ExtraDeckCard = {
    ...conversion.extraDeckCard,
    instanceId: 'bs9-030-demo-extra',
  }
  const flipCardNumbers = conditionMet
    ? ['BS9-026@1', 'BS9-026@2', 'BS9-029', 'BS9-029']
    : ['BS9-026@1', 'BS9-029']
  const flipHand = flipCardNumbers.map((cardNumber, index) =>
    cardCheckOfficialCookie(cardNumber, `bs9-030-hand-flip-${index + 1}`),
  )
  const supportArea = Array.from({ length: 3 }, (_, index) => ({
    card: cardCheckOfficialCard('BS8-046', `bs9-030-yellow-support-${index + 1}`),
    rested: false,
  }))
  const breakCookie = cardCheckOfficialCookie('BS9-006', 'bs9-030-break-lv1')
  const player = base.players['player-one']
  return {
    ...base,
    extraDeckPlayUsedThisTurn: false,
    pendingOnPlay: null,
    pendingBattle: null,
    commandLog: [],
    players: {
      ...base.players,
      'player-one': {
        ...player,
        hand: flipHand,
        supportArea,
        breakArea: [breakCookie],
        extraDeck: [extraCard],
      },
    },
  }
}

/**
 * BS9 FLIP 的共同攻擊後驗證入口。以真實 BS9-030 Shadow Milk Cookie
 * 完成 EXTRA 登場代價、On Play 與三點攻擊，停在「棄置 1 張具有 FLIP
 * 的 Cookie」的攻擊後待處理狀態；指定的 BS9 FLIP 卡留在手牌，供玩家
 * 透過正式 optional-cost／FLIP UI 支付並發動。這讓 BS9-031／032 的
 * card-check 不再用 P-018 效果傷害捏造 HP 翻牌作為唯一正向入口。
 */
function createBs9ShadowMilkDetachedFlipDemoState(cardNumber: string): GameState {
  const base = createBs9030ExtraDeckDemoState(true)
  const extra = base.players['player-one'].extraDeck?.[0]
  if (!extra) throw new Error('BS9 FLIP fixture requires the BS9-030 EXTRA card')

  const detachedFlip = cardCheckOfficialCard(
    cardNumber,
    `bs9-${cardNumber.toLowerCase()}-detached-flip`,
  )
  if (detachedFlip.type !== 'cookie' || !detachedFlip.flip) {
    throw new Error(`BS9 detached FLIP fixture requires a Cookie with FLIP: ${cardNumber}`)
  }

  // Keep the requested FLIP card at index 1.  The other three real yellow
  // FLIP Cookies are consumed by BS9-030's EXTRA entry cost, leaving the
  // requested card as the only legal detached-FLIP candidate.
  const entryFlipCards = [
    cardCheckOfficialCookie('BS9-026@1', 'bs9-030-detached-entry-1'),
    cardCheckOfficialCookie('BS9-029', 'bs9-030-detached-entry-2'),
    cardCheckOfficialCookie('BS9-029@1', 'bs9-030-detached-entry-3'),
  ]
  const flipDiscardCostCards = Array.from(
    { length: detachedFlip.flip.cost.discardHand ?? 0 },
    (_, index) => cardCheckOfficialCard(
      'BS8-021',
      `bs9-${cardNumber.toLowerCase()}-detached-cost-${index + 1}`,
    ),
  )
  const prepared: GameState = {
    ...base,
    players: {
      ...base.players,
      'player-one': {
        ...base.players['player-one'],
        hand: [entryFlipCards[0]!, detachedFlip, ...entryFlipCards.slice(1), ...flipDiscardCostCards],
        // Leave Shadow Milk as the only friendly Cookie after it enters so
        // each requested FLIP has one unambiguous target on the real board.
        battleArea: [],
      },
    },
  }

  let state = applyGameCommand(prepared, {
    kind: 'play-extra-deck-cookie',
    playerId: 'player-one',
    instanceId: extra.instanceId,
  })
  const entryPaymentIds = state.players['player-one'].hand
    .filter((card) => card.instanceId !== detachedFlip.instanceId && card.flip)
    .slice(0, 3)
    .map((card) => card.instanceId)
  if (entryPaymentIds.length !== 3) {
    throw new Error(`BS9 detached FLIP fixture cannot pay BS9-030 entry: ${cardNumber}`)
  }
  state = applyGameCommand(state, {
    kind: 'resolve-optional-cost-attack',
    playerId: 'player-one',
    action: 'pay',
    discardCardIds: entryPaymentIds,
    paymentIds: [],
  })
  state = applyGameCommand(state, {
    kind: 'begin-activate-skill',
    playerId: 'player-one',
    sourceInstanceId: extra.instanceId,
    trigger: 'on-play',
    paymentIds: [],
  })
  const breakTarget = state.players['player-one'].breakArea[0]
  if (!breakTarget) throw new Error(`BS9 detached FLIP fixture requires an LV.1 break target: ${cardNumber}`)
  state = applyGameCommand(state, {
    kind: 'resolve-ability-effect',
    playerId: 'player-one',
    targetIds: [breakTarget.instanceId],
  })

  const attacker = state.players['player-one'].battleArea.find(
    (entry) => entry.card.instanceId === extra.instanceId,
  )
  const target = state.players['player-two'].battleArea[0]
  if (!attacker || !target) {
    throw new Error(`BS9 detached FLIP fixture requires both attack entries: ${cardNumber}`)
  }
  state = applyGameCommand(state, {
    kind: 'declare-attack',
    playerId: 'player-one',
    attackerInstanceId: attacker.card.instanceId,
    targetInstanceId: target.card.instanceId,
    supportPaymentIds: state.players['player-one'].supportArea.map(
      (support) => support.card.instanceId,
    ),
  })
  state = applyGameCommand(state, { kind: 'skip-trap', playerId: 'player-two' })
  let damageSteps = 0
  while (state.pendingBattle?.stage === 'damage' && damageSteps < 10) {
    state = applyGameCommand(state, {
      kind: 'resolve-next-damage',
      playerId: 'player-two',
    })
    damageSteps += 1
  }
  state = applyGameCommand(state, {
    kind: 'resolve-attack-effect',
    playerId: 'player-one',
    targetIds: [],
  })
  if (state.pendingOptionalCostAttack?.sourceInstanceId !== extra.instanceId) {
    throw new Error(`BS9-030 attack-after did not expose detached FLIP: ${cardNumber}`)
  }
  return state
}

/**
 * BS9-055 Shadow Milk Cookie 的候選 EXTRA fixture。卡面是直接進入戰鬥區的
 * EXTRA（不是 Awaken）：登場條件使用本回合支援區送棄計數與對手支援張數，
 * 進場後的 Activate 則另外由同一張 ExtraDeckCard 的 `skill` 提供。
 */
function createBs9055ExtraDeckDemoState(
  conditionMet: boolean,
  variantCardNumber = 'BS9-055',
): GameState {
  const base = createBs8ExtraDeckDemoState(false)
  const source = (bs9CandidateDocument.cards as OfficialCardRecord[]).find(
    (record) => record.cardNumber === variantCardNumber,
  ) ?? (bs9CandidateDocument.cards as OfficialCardRecord[]).find(
    (record) => record.baseCardNumber === 'BS9-055',
  )
  if (!source) throw new Error('BS9-055 fixture requires the candidate EXTRA record')
  const conversion = convertOfficialCardToExtraDeckCard(source, 'bs9-055-demo')
  if (conversion.status !== 'converted') {
    throw new Error(`BS9-055 fixture cannot convert the candidate EXTRA card: ${conversion.reason}`)
  }
  const extraCard: ExtraDeckCard = {
    ...conversion.extraDeckCard,
    instanceId: 'bs9-055-demo-extra',
  }
  const p1 = base.players['player-one']
  const p2 = base.players['player-two']
  const supportArea = Array.from({ length: 4 }, (_, index) => ({
    card: cardCheckOfficialCard('BS8-071', `bs9-055-green-support-${index + 1}`),
    rested: false,
  }))
  const opponentSupportArea = Array.from({ length: conditionMet ? 3 : 2 }, (_, index) => ({
    card: cardCheckOfficialCard('BS8-021', `bs9-055-opponent-support-${index + 1}`),
    rested: false,
  }))
  return {
    ...base,
    extraDeckPlayUsedThisTurn: false,
    pendingOnPlay: null,
    pendingBattle: null,
    commandLog: [],
    supportCardsTrashedThisTurn: {
      'player-one': conditionMet ? 2 : 1,
      'player-two': 0,
    },
    players: {
      ...base.players,
      'player-one': {
        ...p1,
        extraDeck: [extraCard],
        supportArea,
        // Five HP cards are consumed by the direct EXTRA entry; the next
        // physical support is therefore the Activate deck-top witness.
        deck: [
          ...bs9PhysicalDeck('bs9-055-hp', 5),
          cardCheckOfficialCard('BS8-071', 'bs9-055-deck-support'),
          ...bs9PhysicalDeck('bs9-055-deck-tail', 12),
        ],
      },
      'player-two': {
        ...p2,
        supportArea: opponentSupportArea,
      },
    },
  }
}

/**
 * BS9-055 的 attack-only Browser lane。像其他 `card-attack:` fixture 一樣，
 * 這裡從普通攻擊費用已支付、等待攻擊後效果的觀察點開始；EXTRA 登場本身
 * 仍先透過正式 play-extra-deck-cookie 命令建立，避免 Browser 測試跳過進場
 * 分類。負向路徑只移除 Then 返回手牌所需的最後一張支援卡。
 */
function createBs9055ExtraDeckAttackDemoState(
  variantCardNumber: string,
  blocked: boolean,
): GameState {
  let state = createBs9055ExtraDeckDemoState(true, variantCardNumber)
  const extra = state.players['player-one'].extraDeck?.[0]
  if (!extra) throw new Error('BS9-055 attack fixture requires an EXTRA card')
  state = applyGameCommand(state, {
    kind: 'play-extra-deck-cookie',
    playerId: 'player-one',
    instanceId: extra.instanceId,
  })
  const source = state.players['player-one'].battleArea.find(
    (entry) => entry.card.id === 'BS9-055',
  )
  const target = state.players['player-two'].battleArea[0]
  if (!source || !target) throw new Error('BS9-055 attack fixture requires battle entries')
  const remainingSupports = blocked
    ? []
    : state.players['player-one'].supportArea.slice(0, 2)
  return {
    ...state,
    players: {
      ...state.players,
      'player-one': {
        ...state.players['player-one'],
        supportArea: remainingSupports,
        battleArea: state.players['player-one'].battleArea.map((entry) =>
          entry.card.instanceId === source.card.instanceId
            ? { ...entry, rested: true }
            : entry,
        ),
      },
    },
    pendingBattle: {
      attackerPlayerId: 'player-one',
      defenderPlayerId: 'player-two',
      attackerInstanceId: source.card.instanceId,
      targetInstanceId: target.card.instanceId,
      declaredDamage: source.card.attack,
      remainingDamage: 0,
      stage: 'attack-effect',
      trapUsed: false,
      revealedHpCard: null,
      preventKnockoutTargetIds: [],
      faintedColors: [],
      attackEffects: source.card.attackEffects ?? [],
      attackEffectIndex: 0,
    },
  }
}

/**
 * Build the remaining BS8 EXTRA cards' isolated Browser fixtures.  These
 * snapshots deliberately use the same `playExtraDeckCookie` command as a
 * real match; only the surrounding board state is arranged to make one
 * printed requirement true or false.  They never enter the Standard deck or
 * generated card-pool registry.
 */
function createBs8ExtraDeckScenarioState(
  cardNumber: Exclude<Bs8ExtraDeckCardNumber, 'BS8-005'>,
  conditionMet: boolean,
  variantCardNumber: string = cardNumber,
): GameState {
  const base = createBs8ExtraDeckDemoState(false)
  const extraSource = (bs8FormalDocument.cards as OfficialCardRecord[]).find(
    (record) =>
      record.baseCardNumber === cardNumber &&
      record.cardNumber === variantCardNumber,
  ) ?? (bs8FormalDocument.cards as OfficialCardRecord[]).find(
    (record) => record.baseCardNumber === cardNumber,
  )
  if (!extraSource) {
    throw new Error(`${cardNumber} fixture requires the formal EXTRA card record`)
  }
  const extraConversion = convertOfficialCardToExtraDeckCard(
    extraSource,
    `demo-${cardNumber.toLowerCase()}`,
  )
  if (extraConversion.status !== 'converted') {
    throw new Error(
      `${cardNumber} fixture cannot convert the formal EXTRA card: ${extraConversion.reason}`,
    )
  }
  const extraCard: ExtraDeckCard = {
    ...extraConversion.extraDeckCard,
    instanceId: `bs8-${cardNumber.slice(4).toLowerCase()}-demo-extra`,
  }

  const makeFormalCookie = (cardNumber: string, instanceId: string): CookieCard => {
    const source = (bs8FormalDocument.cards as OfficialCardRecord[]).find(
      (record) => record.cardNumber === cardNumber,
    ) ?? (bs8FormalDocument.cards as OfficialCardRecord[]).find(
      (record) => record.baseCardNumber === cardNumber,
    )
    if (!source) throw new Error(`${cardNumber} fixture requires its base Cookie card`)
    const conversion = convertOfficialCardToGameCard(
      source,
      `demo-${cardNumber.toLowerCase()}`,
    )
    if (
      conversion.status !== 'converted' ||
      conversion.gameCard.type !== 'cookie'
    ) {
      throw new Error(`${cardNumber} fixture cannot convert its base Cookie card`)
    }
    return { ...conversion.gameCard, instanceId }
  }

  const player = base.players['player-one']
  const opponent = base.players['player-two']
  let playerUpdate: Partial<PlayerState>
  let opponentUpdate: Partial<PlayerState> = {}

  if (cardNumber === 'BS8-069') {
    const opponentSupports = Array.from({ length: conditionMet ? 5 : 3 }, (_, index) => ({
      card: makeFormalCookie('BS8-070', `bs8-069-opponent-support-${index + 1}`),
      rested: false,
    }))
    playerUpdate = {
      supportArea: Array.from({ length: 3 }, (_, index) => ({
        card: makeFormalCookie('BS8-070', `bs8-069-player-support-${index + 1}`),
        rested: false,
      })),
      discardPile: [testSupportCard('bs8-069-green-trash', 'green')],
    }
    opponentUpdate = { supportArea: opponentSupports }
  } else if (cardNumber === 'BS8-090') {
    const blueTarget = cardCheckFillerCookie(
      'bs8-090-blue-target',
      2,
      4,
      0,
      'blue',
    )
    playerUpdate = {
      supportArea: Array.from({ length: 3 }, (_, index) => ({
        card: makeFormalCookie('BS8-091', `bs8-090-blue-support-${index + 1}`),
        rested: false,
      })),
      hand: Array.from({ length: conditionMet ? 2 : 3 }, (_, index) =>
        testSupportCard(`bs8-090-hand-${index + 1}`, 'blue'),
      ),
      battleArea: [cardCheckBattleEntry(blueTarget.cookie, blueTarget.hpCards, 1)],
    }
  } else {
    const awakenBase =
      cardNumber === 'BS8-027'
        ? makeFormalCookie('BS8-026', 'bs8-027-awaken-target')
        : makeFormalCookie('BS8-103', 'bs8-104-awaken-target')
    const playedFrom = cardNumber === 'BS8-027' ? 'break' : 'trash'
    playerUpdate = {
      ...(cardNumber === 'BS8-027' ? {
        supportArea: Array.from({ length: 3 }, (_, index) => ({
          card: makeFormalCookie('BS8-026', `bs8-027-yellow-support-${index + 1}`),
          rested: false,
        })),
      } : {
        supportArea: Array.from({ length: 4 }, (_, index) => ({
          card: makeFormalCookie('BS8-105', `bs8-104-purple-support-${index + 1}`),
          rested: false,
        })),
      }),
      battleArea: [
        {
          ...cardCheckBattleEntry(
            awakenBase,
            Array.from({ length: Math.max(2, awakenBase.hp - 1) }, (_, index) =>
              testSupportCard(`bs8-${cardNumber.slice(4)}-awaken-hp-${index + 1}`),
            ),
            1,
          ),
          enteredFrom: conditionMet ? playedFrom : 'hand',
          enteredTurn: conditionMet ? base.turnNumber : base.turnNumber - 1,
        },
      ],
      hand:
        cardNumber === 'BS8-104'
          ? [testSupportCard('bs8-104-on-play-discard', 'purple')]
          : [],
      discardPile:
        cardNumber === 'BS8-104'
          ? [testSupportCard('bs8-104-purple-return', 'purple')]
          : [],
    }
  }

  if (cardNumber === 'BS8-027') {
    const first = opponent.battleArea[0]
    opponentUpdate = {
      ...opponentUpdate,
      battleArea: [first, {
        ...first,
        card: { ...first.card, instanceId: 'bs8-027-second-opponent' },
        hpCards: first.hpCards.map((card, index) => ({ ...card, instanceId: `bs8-027-second-hp-${index}` })),
        battleEntryId: 'bs8-027-second-opponent:entry',
      }],
    }
  }

  return {
    ...base,
    extraDeckPlayUsedThisTurn: false,
    pendingOnPlay: null,
    pendingBattle: null,
    commandLog: [],
    players: {
      ...base.players,
      'player-one': {
        ...player,
        ...playerUpdate,
        extraDeck: [extraCard],
      },
      'player-two': {
        ...opponent,
        ...opponentUpdate,
      },
    },
  }
}

/**
 * 僅供 `card:BS8-005`／`card-negative:BS8-005` 的 localhost Browser A/B。
 *
 * 這個 fixture 不直接填寫 `cookiesFaintedThisTurn` 來假裝條件成立，而是
 * 透過正式 BS8-011「Saffron Buffalo Shaman」技能各造成一次 1 點效果傷害：
 * 第一張讓另一張昏厥、補位後第二張再讓第一張昏厥。兩次支付、目標、昏厥
 * 與補位都走 `applyGameCommand`，所以 EXTRA 登場條件讀到的是規則結算後
 * 的實際本回合昏厥計數。負向路徑只完成第一次技能，保留 1 次昏厥。
 */
export const createBs8ExtraDeckReadinessDemoState = (
  conditionMet: boolean,
  variantCardNumber = 'BS8-005',
): GameState => {
  const base = createBs8ExtraDeckDemoState(false, 'BS8-005', variantCardNumber)
  const saffronSource = (bs8FormalDocument.cards as OfficialCardRecord[]).find(
    (record) => record.cardNumber === 'BS8-011',
  )
  if (!saffronSource) {
    throw new Error('BS8-005 readiness fixture requires BS8-011')
  }
  const saffronConversion = convertOfficialCardToGameCard(
    saffronSource,
    'bs8-005-readiness',
  )
  if (
    saffronConversion.status !== 'converted' ||
    saffronConversion.gameCard.type !== 'cookie'
  ) {
    throw new Error('BS8-005 readiness fixture cannot convert BS8-011')
  }

  const saffronCard = saffronConversion.gameCard
  const makeSaffron = (instanceId: string): CookieCard => ({
    ...saffronCard,
    instanceId,
  })
  const firstSaffron = makeSaffron('bs8-005-readiness-saffron-a')
  const secondSaffron = makeSaffron('bs8-005-readiness-saffron-b')
  const replacementSaffron = makeSaffron('bs8-005-readiness-saffron-c')
  const player = base.players['player-one']
  const opponent = base.players['player-two']
  const opponentTarget = opponent.battleArea[0]
  const paymentIds = player.supportArea
    .slice(0, 2)
    .map((support) => support.card.instanceId)
  if (paymentIds.length !== 2 || !opponentTarget) {
    throw new Error('BS8-005 readiness fixture requires two payments and a target')
  }

  const hpCard = (instanceId: string): GameCard =>
    testSupportCard(instanceId)
  let state: GameState = {
    ...base,
    firstPlayerId: 'player-one',
    activePlayerId: 'player-one',
    phase: 'main',
    turnNumber: 2,
    cookiesFaintedThisTurn: { 'player-one': 0, 'player-two': 0 },
    departedCookieCounts: { 'player-one': 0, 'player-two': 0 },
    pendingBattle: null,
    pendingReplacement: null,
    extraDeckPlayUsedThisTurn: false,
    commandLog: [],
    players: {
      ...base.players,
      'player-one': {
        ...player,
        hand: [replacementSaffron],
        battleArea: [
          cardCheckBattleEntry(
            firstSaffron,
            [hpCard('bs8-005-readiness-a-hp')],
            1,
          ),
          cardCheckBattleEntry(
            secondSaffron,
            [hpCard('bs8-005-readiness-b-hp')],
            2,
          ),
        ],
        supportArea: player.supportArea.map((support) => ({
          ...support,
          rested: false,
        })),
        breakArea: [],
      },
      'player-two': {
        ...opponent,
        battleArea: [opponentTarget],
      },
    },
  }

  state = applyGameCommand(state, {
    kind: 'activate-skill',
    playerId: 'player-one',
    sourceInstanceId: firstSaffron.instanceId,
    trigger: 'activate',
    paymentIds: [paymentIds[0]],
    effectTargets: [
      [secondSaffron.instanceId, opponentTarget.card.instanceId],
    ],
  })
  state = applyGameCommand(state, {
    kind: 'replace-cookie',
    playerId: 'player-one',
    instanceId: replacementSaffron.instanceId,
  })

  if (!conditionMet) return state

  state = applyGameCommand(state, {
    kind: 'activate-skill',
    playerId: 'player-one',
    sourceInstanceId: replacementSaffron.instanceId,
    trigger: 'activate',
    paymentIds: [paymentIds[1]],
    effectTargets: [
      [firstSaffron.instanceId, opponentTarget.card.instanceId],
    ],
  })
  return applyGameCommand(state, {
    kind: 'skip-replacement',
    playerId: 'player-one',
  })
}

/**
 * 僅供 localhost Browser A/B 的 BS8-076 下一個 Active Phase 情境。它直接
 * 放在規則引擎已建立的「選擇 0 張或恰好 2 張手牌」決策點，讓 Browser 驗證
 * 實際 command 能令目標保持 rested 或恢復 active；不屬於 Standard 牌池／對戰。
 */
export const createBs8076ActivePreventionDemoState = (): GameState => {
  const state = createCardCheckDemoState('BS8-076')
  const player = state.players['player-one']
  const target = player.battleArea.find(
    (entry) => entry.card.instanceId === 'self-extra-1',
  )
  if (!target) throw new Error('BS8-076 active-phase fixture requires its target Cookie')

  const targetCard = {
    ...target.card,
    name: 'BS8-076 Active Phase Target',
  }
  const source = {
    sourcePlayerId: 'player-two' as const,
    sourceInstanceId: 'bs8-076-active-prevention-source',
    sourceCardName: 'Icicle Yeti Cookie',
    effectText:
      'During your opponent\'s next Active Phase, that Cookie is not set as active unless your opponent discards 2 cards from their hand.',
  }

  return {
    ...state,
    activePlayerId: 'player-one',
    phase: 'active',
    pendingBattle: null,
    players: {
      ...state.players,
      'player-one': {
        ...player,
        hand: [
          testSupportCard('bs8-076-active-discard-1', 'blue'),
          testSupportCard('bs8-076-active-discard-2', 'blue'),
        ],
        battleArea: player.battleArea.map((entry) =>
          entry.card.instanceId === target.card.instanceId
            ? { ...entry, card: targetCard, rested: true }
            : entry,
        ),
      },
    },
    conditionalCookieActivePreventions: {
      'player-one': [
        {
          ...source,
          cookieInstanceId: targetCard.instanceId,
          discardHandToSetActive: 2,
        },
      ],
    },
    pendingOpponentHandDiscard: {
      playerId: 'player-one',
      count: 2,
      optional: true,
      ...source,
      activePhaseCookieInstanceId: targetCard.instanceId,
    },
  }
}

/**
 * BS8-084 的獨立 Browser A/B：攻擊方必須先棄 1 張手牌，才能攻擊休息中的
 * Sherbet Cookie。此情境只供 localhost candidate 驗收使用，不會把 BS8
 * 加入正式卡池或一般牌組。
 */
export const createBs8084AttackRequirementDemoState = (
  payable: boolean,
): GameState => {
  const state = createCardCheckDemoState('BS8-084')
  const sherbet = state.players['player-one'].battleArea.find(
    (entry) => entry.card.id === 'BS8-084',
  )
  if (!sherbet) {
    throw new Error('BS8-084 attack-discard fixture requires Sherbet Cookie')
  }

  const attacker = cardCheckFillerCookie(
    'player-one-bs8-084-tax-attacker',
    1,
    3,
    0,
    'blue',
  )
  const defender: CookieCard = {
    ...sherbet.card,
    instanceId: 'player-two-BS8-084-tax-defender',
  }
  const defenderHpCards = Array.from(
    { length: defender.hp },
    (_, index) => testSupportCard(`BS8-084-tax-defender-hp-${index + 1}`, 'blue'),
  )

  return {
    ...state,
    players: {
      ...state.players,
      'player-one': {
        ...state.players['player-one'],
        // The positive path has exactly one actual card to discard. The
        // negative path has no hand cards, so beginAttack must reject before
        // resting the attacker or starting a pending battle.
        hand: payable
          ? [testSupportCard('BS8-084-required-discard-card', 'blue')]
          : [],
        battleArea: [
          cardCheckBattleEntry(attacker.cookie, attacker.hpCards, 4),
        ],
        supportArea: [],
      },
      'player-two': {
        ...state.players['player-two'],
        hand: [],
        battleArea: [
          cardCheckBattleEntry(defender, defenderHpCards, 1, true),
        ],
        supportArea: [],
      },
    },
    pendingBattle: null,
    pendingOpponentHandDiscard: null,
  }
}

